    fn windows_respect_utf8_boundaries_cjk_and_emoji() {
        let cjk: String = "日本語漢字テスト".repeat(800); // multi-byte, ~40KB+
        let emoji: String = "😀🎉🚀✨".repeat(2000);

        for (label, text) in [("cjk", cjk.as_str()), ("emoji", emoji.as_str())] {
