    #[test]
    fn expand_and_pool_preserves_1to1_order() {
        let texts = vec![
            "short".to_string(),
            "x".repeat(10_000),
            "mid".to_string(),
            "y".repeat(5_000),
        ];
        let (windows, counts) = expand_texts_to_windows(
            &texts,
